  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'CHEMISTRY_ATOMIC_STRUCTURE';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Como ler modelos de átomos, isótopos e íons', 'Use três relações sem misturá-las: Z=P, A=P+N e carga=P−E. O núcleo define o elemento e o isótopo; a eletrosfera define se a espécie é neutra ou um íon.', '## Comece pelo núcleo
O número atômico Z conta prótons. Esse número identifica o elemento: se Z=17, a espécie tem 17 prótons e é cloro, mesmo que tenha ganhado ou perdido elétrons. O número de massa A conta prótons e nêutrons juntos. Portanto, N=A−Z. Elétrons não entram em A.

## Separe isótopo de íon
Isótopos têm o mesmo Z e números de massa diferentes; a diferença está nos nêutrons. Íons têm quantidades diferentes de prótons e elétrons. Para a carga em unidades elementares, q=P−E: carga positiva indica menos elétrons que prótons; carga negativa indica mais elétrons. Na ionização comum, o núcleo permanece igual.

## Leia a notação
Na escrita ⁴⁰₂₀Ca²⁺, o índice inferior esquerdo é Z=20 e o superior esquerdo é A=40; a carga 2+ aparece à direita. Assim, P=20, N=40−20=20 e E=20−2=18. A identidade do cálcio decorre dos 20 prótons, não dos 18 elétrons.

## Massa média não é A de um átomo
A massa atômica mostrada na tabela periódica pode ser fracionária porque representa uma média ponderada das massas isotópicas e de suas abundâncias. Cada nuclídeo individual tem um número inteiro de prótons e nêutrons e, portanto, um A inteiro.

## Exemplo resolvido
Para ³⁷₁₇Cl⁻, Z=17, então P=17; N=A−Z=37−17=20; e q=P−E=−1, então E=18. O símbolo Cl continua válido porque Z não mudou. Comparado a ³⁵Cl, o núcleo tem dois nêutrons a mais: são isótopos do mesmo elemento, e a carga negativa identifica o estado iônico.',
    'Em uma ficha com A=64, Z=30 e carga 2+, primeiro obtenha P=30. Em seguida, N=64−30=34. Por fim, 2=P−E, então E=28. A resposta fica consistente porque 30−28=+2. A sequência evita usar elétrons para calcular A ou nêutrons para identificar o elemento.', array['Anote Z, A e q em colunas separadas antes de calcular.', 'Use P=Z e N=A−Z para o núcleo.', 'Use q=P−E para conferir a eletrosfera.', 'Ao comparar espécies, diga primeiro o que permaneceu igual e só então o que mudou.']::text[], 22, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-chemistry-atomic-structure","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Ler símbolos e números em uma representação simples de átomo.","Somar e subtrair números inteiros."],"key_concepts":["número atômico e identidade do elemento","número de massa e contagem de nucleons","isótopos e variação de nêutrons","íons e variação de elétrons","notação nuclear","média isotópica e número de massa"],"progression":[{"stage":"FOUNDATION","focus":"Relembrar o significado de Z, A e carga em espécies isoladas.","questionIds":[]},{"stage":"APPLICATION","focus":"Calcular partículas a partir de dados de núcleo e eletrosfera.","questionIds":["v5-chem-atomic-practice-01"]},{"stage":"TRANSFER","focus":"Aplicar o modelo a espectrometria, abundância isotópica e ionização.","questionIds":["v5-chem-atomic-transfer-01","v5-chem-atomic-transfer-02","v5-chem-atomic-transfer-03","v5-chem-atomic-transfer-04"]},{"stage":"INTEGRATION","focus":"Combinar isótopos, carga e consistência de registros.","questionIds":["v5-chem-atomic-lock-01","v5-chem-atomic-lock-02","v5-chem-atomic-lock-03"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Revisar notação, identidade e relações quantitativas em contextos variados.","questionIds":["v5-chem-atomic-review-01","v5-chem-atomic-review-02","v5-chem-atomic-review-03","v5-chem-atomic-review-04","v5-chem-atomic-review-05","v5-chem-atomic-review-06"]}],"micro_explanations":[{"trigger":"Z_IDENTIFIES_ELEMENT","text":"O elemento é identificado por Z, a quantidade de prótons."},{"trigger":"A_COUNTS_NUCLEONS","text":"A conta prótons e nêutrons; use N=A−Z."},{"trigger":"CHARGE_SIGN_ELECTRONS","text":"Use q=P−E: sinal positivo indica menos elétrons; negativo, mais."},{"trigger":"ISOTOPE_VS_ION","text":"Isótopos diferem em nêutrons; íons diferem em elétrons."},{"trigger":"IONIZATION_NUCLEUS","text":"Ganhar ou perder elétrons não muda o núcleo na ionização comum."},{"trigger":"AVERAGE_MASS","text":"A massa atômica tabelada é média da amostra; A de um nuclídeo é inteiro."}],"remediations":[{"id":"SEPARATE_Z_A","misconception":"TROCAR_Z_E_A","prompt":"Marque Z como prótons e A como prótons+nêutrons. Subtraia A−Z e confira se P+N=A."},{"id":"TRACE_CHARGE","misconception":"INVERTER_CARGA_E_ELETRONS","prompt":"Escreva q=P−E. Se q é negativo, determine quantos elétrons existem além dos prótons."},{"id":"COMPARE_NUCLEI","misconception":"CONFUNDIR_ISOTOPO_E_ION","prompt":"Compare primeiro Z e N para classificar o núcleo; depois compare P e E para classificar a carga."},{"id":"AUDIT_NOTATION","misconception":"LER_POSICAO_ERRADA","prompt":"Circule o número inferior esquerdo (Z), o superior esquerdo (A) e a carga à direita antes de calcular."},{"id":"AVERAGE_VS_NUCLIDE","misconception":"MEDIA_COMO_NUMERO_DE_MASSA","prompt":"Calcule a média ponderada de abundâncias e compare-a com os valores inteiros de A dos isótopos."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"IUPAC Gold Book: atomic number","publisher":"International Union of Pure and Applied Chemistry","url":"https://goldbook.iupac.org/terms/view/A00499","accessedOn":"2026-10-13","supports":["Z é a quantidade de prótons do núcleo."],"use":"Referência terminológica para validar a definição; exemplos e explicações do pacote são autorais."},{"title":"IUPAC Gold Book: mass number","publisher":"International Union of Pure and Applied Chemistry","url":"https://goldbook.iupac.org/terms/view/M03726","accessedOn":"2026-10-13","supports":["A conta prótons e nêutrons do núcleo."],"use":"Referência terminológica para validar a definição; exemplos e explicações do pacote são autorais."},{"title":"IUPAC Gold Book: isotopes","publisher":"International Union of Pure and Applied Chemistry","url":"https://goldbook.iupac.org/terms/view/I03331","accessedOn":"2026-10-13","supports":["Isótopos têm o mesmo número atômico e diferentes números de massa."],"use":"Referência terminológica para validar a distinção; exemplos e questões do pacote são autorais."},{"title":"Chemistry 2e, Section 2.3: Atomic Structure and Symbolism","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/2-3-atomic-structure-and-symbolism","accessedOn":"2026-10-13","supports":["Interpretação de número atômico, número de massa e símbolos nucleares."],"use":"Conferência conceitual; o pacote não reproduz exercícios ou texto do livro."},{"title":"Chemistry 2e, Section 2.6: Ionic and Molecular Compounds","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/2-6-ionic-and-molecular-compounds","accessedOn":"2026-10-13","supports":["Formação de íons por variação de elétrons sem alteração do número de prótons em reações químicas comuns."],"use":"Conferência conceitual; o pacote não reproduz exercícios ou texto do livro."}],"copyright_note":"Questões, cenários, explicações e dados foram escritos para este pacote. Fontes sustentam a precisão conceitual; o alinhamento curricular oficial e a revisão pedagógica humana permanecem pendentes.","objective":"Interpretar Z, A e carga para determinar prótons, nêutrons e elétrons, distinguir isótopos de íons e justificar conclusões a partir de modelos e dados.","common_mistake":"Usar A como se fosse o número de prótons, incluir elétrons no número de massa, ou tratar uma transferência de elétrons como mudança de elemento ou de isótopo.","estimated_minutes":22}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'v5-chemistry-atomic-structure' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-chem-atomic-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"PHOSPHORUS_ION_PARTICLE_TABLE","statement":"Um modelo de uma espécie de fósforo informa número de massa A=31, número atômico Z=15 e carga 3−. Quantos prótons, nêutrons e elétrons ela possui?","options":["15 prótons, 16 nêutrons e 18 elétrons.","31 prótons, 15 nêutrons e 18 elétrons.","15 prótons, 16 nêutrons e 12 elétrons.","15 prótons, 31 nêutrons e 18 elétrons."],"correctAnswer":"15 prótons, 16 nêutrons e 18 elétrons.","explanation":"Z fornece 15 prótons. N=A−Z=31−15=16. A carga −3 indica três elétrons a mais que prótons, portanto E=18. A identidade do fósforo permanece ligada aos 15 prótons.","errorFocus":"Confundir A com prótons ou inverter o efeito do sinal da carga na contagem de elétrons.","hint":"Calcule primeiro P=Z e N=A−Z; depois use carga=P−E para encontrar E.","misconceptions":{"31 prótons, 15 nêutrons e 18 elétrons.":["CONFUNDIR_A_COM_PR_TONS_OU_INVERTER_O_EFEITO_DO_SINAL_DA_CARGA_NA_CONTAGEM_DE_EL_TRONS"]},"position":1},{"id":"v5-chem-atomic-transfer-01","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"CALCULATE","contextFamily":"BORON_ISOTOPE_ABUNDANCE","statement":"Uma amostra de boro contém 20% de átomos com A=10 e 80% com A=11. Qual massa atômica média aproximada descreve a amostra e como interpretá-la?","options":["10,5 u; cada átomo contém exatamente 10,5 núcleons.","10,8 u; é uma média ponderada, não o número de massa de cada átomo.","10,8 u; todos os átomos têm número de massa 10,8.","11 u; a média deve ser sempre o número de massa do isótopo mais abundante."],"correctAnswer":"10,8 u; é uma média ponderada, não o número de massa de cada átomo.","explanation":"A média ponderada é 0,20×10 + 0,80×11 = 10,8 u. Núcleos individuais têm números de massa inteiros; a média representa a composição da amostra.","errorFocus":"Tratar uma média de abundâncias como se fosse o número de massa de um núcleo individual.","hint":"Multiplique cada número de massa por sua fração e some os produtos; depois distinga média de A.","misconceptions":{"10,5 u; cada átomo contém exatamente 10,5 núcleons.":["TRATAR_UMA_M_DIA_DE_ABUND_NCIAS_COMO_SE_FOSSE_O_N_MERO_DE_MASSA_DE_UM_N_CLEO_INDIVIDUAL"]},"position":1},{"id":"v5-chem-atomic-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"ZINC_MASS_SPECTRUM_COUNTS","statement":"Um registro de espectrometria descreve uma espécie com 30 prótons, 34 nêutrons e 28 elétrons. Qual identificação é compatível com os dados?","options":["É o átomo neutro ⁶⁴Zn, pois prótons e nêutrons somam 64.","É o íon ⁶²Zn²⁻, pois os elétrons determinam o número de massa.","É o íon ⁶⁴Zn²⁺: A=64 e há duas cargas positivas líquidas.","É o íon ⁶⁴Cu²⁺, pois a carga define o elemento."],"correctAnswer":"É o íon ⁶⁴Zn²⁺: A=64 e há duas cargas positivas líquidas.","explanation":"Z=30 identifica zinco. A=30+34=64; como P−E=30−28=+2, a espécie tem carga 2+. O número de massa não inclui elétrons.","errorFocus":"Usar elétrons para identificar o elemento ou incluí-los no número de massa.","hint":"Use separadamente Z=P, A=P+N e carga=P−E.","misconceptions":{"É o átomo neutro ⁶⁴Zn, pois prótons e nêutrons somam 64.":["USAR_EL_TRONS_PARA_IDENTIFICAR_O_ELEMENTO_OU_INCLU_LOS_NO_N_MERO_DE_MASSA"]},"position":2},{"id":"v5-chem-atomic-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"HYDROGEN_ISOTOPES_AFTER_IONIZATION","statement":"Um laboratório remove um elétron de cada átomo neutro de hidrogênio-1 e hidrogênio-2. Após a ionização, qual diferença entre os núcleos permanece?","options":["Os dois passam a ter o mesmo núcleo, pois perderam o elétron.","O hidrogênio-1 fica com um próton a mais que o hidrogênio-2.","A ionização aumenta o número de massa de cada núcleo em uma unidade.","O hidrogênio-1 não tem nêutron e o hidrogênio-2 tem um; ambos ficam com carga +1."],"correctAnswer":"O hidrogênio-1 não tem nêutron e o hidrogênio-2 tem um; ambos ficam com carga +1.","explanation":"Os dois isótopos continuam com um próton, mas têm números diferentes de nêutrons. Remover elétron altera a carga, não o núcleo; cada espécie fica com carga +1.","errorFocus":"Confundir mudança na nuvem eletrônica com alteração do núcleo ou da identidade isotópica.","hint":"Separe núcleo (P e N) de eletrosfera (E) e recalcule cada parte após a ionização.","misconceptions":{"Os dois passam a ter o mesmo núcleo, pois perderam o elétron.":["CONFUNDIR_MUDAN_A_NA_NUVEM_ELETR_NICA_COM_ALTERA_O_DO_N_CLEO_OU_DA_IDENTIDADE_ISOT_PICA"]},"position":3},{"id":"v5-chem-atomic-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"MASS_TO_CHARGE_TWO_STATES","statement":"Um espectrômetro separa o mesmo nuclídeo em sinais de íons 1+ e 2+. Supondo que nenhuma reação nuclear ocorreu, que conclusão é sustentada?","options":["O núcleo conserva prótons e nêutrons; os íons diferem por um elétron e pela carga.","O íon 2+ tem um próton a menos, por isso o elemento muda.","O número de massa aumenta em uma unidade quando a carga passa a 2+.","Os sinais precisam corresponder a isótopos diferentes, pois toda carga altera nêutrons."],"correctAnswer":"O núcleo conserva prótons e nêutrons; os íons diferem por um elétron e pela carga.","explanation":"Ionização retira elétrons sem modificar o núcleo. As duas espécies mantêm Z e A; a espécie 2+ perdeu um elétron a mais que a 1+.","errorFocus":"Interpretar a mudança de carga como mudança do elemento ou do número de massa.","hint":"Compare P e N para a parte nuclear e só depois compare a quantidade de elétrons.","misconceptions":{"O íon 2+ tem um próton a menos, por isso o elemento muda.":["INTERPRETAR_A_MUDAN_A_DE_CARGA_COMO_MUDAN_A_DO_ELEMENTO_OU_DO_N_MERO_DE_MASSA"]},"position":4},{"id":"v5-chem-atomic-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"CHLORINE_ISOTOPE_IONS_TABLE","statement":"Uma tabela traz I: 17 prótons, 18 nêutrons e 18 elétrons; II: 17 prótons, 20 nêutrons e 18 elétrons. Qual comparação reúne corretamente elemento, isótopo e carga?","options":["I é Cl neutro e II é Ar⁻, pois o número de massa mudou.","Ambas são íons Cl⁻; são isótopos com A=35 e A=37, respectivamente.","Ambas são o mesmo nuclídeo porque têm o mesmo número de elétrons.","I é Cl⁺ e II é Cl²⁺, pois há mais nêutrons do que prótons."],"correctAnswer":"Ambas são íons Cl⁻; são isótopos com A=35 e A=37, respectivamente.","explanation":"As duas têm Z=17, então são cloro. Seus números de massa são 35 e 37, logo diferem em nêutrons; 18 elétrons para 17 prótons dá carga −1 em ambas.","errorFocus":"Deixar nêutrons ou elétrons substituírem o número de prótons na identificação do elemento.","hint":"Calcule Z, A e P−E em colunas distintas para cada linha.","misconceptions":{"I é Cl neutro e II é Ar⁻, pois o número de massa mudou.":["DEIXAR_N_UTRONS_OU_EL_TRONS_SUBSTITU_REM_O_N_MERO_DE_PR_TONS_NA_IDENTIFICA_O_DO_ELEMENTO"]},"position":1},{"id":"v5-chem-atomic-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DEBUG","contextFamily":"CALCIUM_ION_MODEL_AUDIT","statement":"Um relatório para ⁴⁰Ca²⁺ registra 20 prótons, 20 nêutrons e 22 elétrons. Qual revisão corrige a inconsistência sem alterar o núcleo?","options":["Deve ter 22 prótons, pois a carga positiva aumenta Z.","Deve ter 40 elétrons, pois A representa a quantidade de elétrons.","A espécie deve ter 18 elétrons; Ca²⁺ perdeu dois elétrons do átomo neutro.","Deve ter 20 elétrons; a carga 2+ não afeta a eletrosfera."],"correctAnswer":"A espécie deve ter 18 elétrons; Ca²⁺ perdeu dois elétrons do átomo neutro.","explanation":"Z=20 define 20 prótons e A−Z=20 nêutrons. A carga +2 exige P−E=2, portanto E=18. A linha confundiu perda de elétrons com ganho.","errorFocus":"Aplicar a carga no sentido errado ou usar A como contagem de elétrons.","hint":"Confira primeiro o núcleo e use depois a equação carga=P−E.","misconceptions":{"Deve ter 22 prótons, pois a carga positiva aumenta Z.":["APLICAR_A_CARGA_NO_SENTIDO_ERRADO_OU_USAR_A_COMO_CONTAGEM_DE_EL_TRONS"]},"position":2},{"id":"v5-chem-atomic-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"SULFUR_ISOTOPE_ION_COMPARISON","statement":"Espécie I tem Z=16, A=32 e 18 elétrons. Espécie II tem Z=16, A=34 e 16 elétrons. Qual descrição é correta?","options":["I é oxigênio e II é enxofre, pois os números de massa diferem.","Ambas são enxofre neutro, pois têm 16 prótons.","I é S²⁺ com 16 nêutrons e II é S²⁻ com 18 nêutrons.","São isótopos de enxofre; I é S²⁻ com 16 nêutrons e II é S neutro com 18 nêutrons."],"correctAnswer":"São isótopos de enxofre; I é S²⁻ com 16 nêutrons e II é S neutro com 18 nêutrons.","explanation":"Z=16 identifica enxofre nas duas espécies. I tem N=32−16=16 e carga 16−18=−2; II tem N=34−16=18 e carga zero.","errorFocus":"Misturar a classificação isotópica, determinada por A e Z, com a carga, determinada por P−E.","hint":"Calcule N=A−Z e carga=P−E independentemente para cada espécie.","misconceptions":{"I é oxigênio e II é enxofre, pois os números de massa diferem.":["MISTURAR_A_CLASSIFICA_O_ISOT_PICA_DETERMINADA_POR_A_E_Z_COM_A_CARGA_DETERMINADA_POR_P_E"]},"position":3},{"id":"v5-chem-atomic-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"RECALL","contextFamily":"POTASSIUM_NUCLEUS_REVIEW","statement":"Uma amostra contém o nuclídeo ³⁹K neutro. O potássio tem Z=19. Quantos prótons, nêutrons e elétrons há em cada átomo?","options":["19 prótons, 20 nêutrons e 19 elétrons.","39 prótons, 19 nêutrons e 19 elétrons.","19 prótons, 39 nêutrons e 20 elétrons.","20 prótons, 19 nêutrons e 19 elétrons."],"correctAnswer":"19 prótons, 20 nêutrons e 19 elétrons.","explanation":"Z=19 fornece prótons; N=39−19=20; a neutralidade iguala elétrons e prótons.","errorFocus":"Trocar A e Z ou esquecer que neutralidade exige P=E.","hint":"Aplique P=Z, N=A−Z e, para átomo neutro, E=P.","misconceptions":{"39 prótons, 19 nêutrons e 19 elétrons.":["TROCAR_A_E_Z_OU_ESQUECER_QUE_NEUTRALIDADE_EXIGE_P_E"]},"position":1},{"id":"v5-chem-atomic-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"FLUORIDE_ELECTRON_COUNT","statement":"Em uma solução, uma espécie de flúor apresenta 9 prótons e 10 elétrons. Qual informação é possível obter mesmo sem saber seus nêutrons?","options":["É F neutro e seu número de massa é 19.","É F⁻, pois tem um elétron a mais que prótons; o número de massa continua desconhecido.","É Ne⁺, porque 10 elétrons definem o elemento neônio.","É F⁺, pois a presença de prótons supera a de elétrons."],"correctAnswer":"É F⁻, pois tem um elétron a mais que prótons; o número de massa continua desconhecido.","explanation":"Nove prótons identificam flúor. Um elétron a mais dá carga −1. Sem a contagem de nêutrons, não é possível determinar A.","errorFocus":"Inferir o número de massa ou o elemento a partir dos elétrons isoladamente.","hint":"Para o elemento use P; para carga use P−E; para A ainda é necessário N.","misconceptions":{"É F neutro e seu número de massa é 19.":["INFERIR_O_N_MERO_DE_MASSA_OU_O_ELEMENTO_A_PARTIR_DOS_EL_TRONS_ISOLADAMENTE"]},"position":2},{"id":"v5-chem-atomic-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"NITROGEN_ISOTOPE_LABELS","statement":"Dois átomos neutros aparecem identificados como ¹⁴N e ¹⁵N. Qual propriedade explica por que ambos são nitrogênio, embora tenham massas diferentes?","options":["Ambos têm A=7 e diferem no número de elétrons.","O mais pesado tem um próton a mais, mas continua sendo o mesmo elemento.","Ambos têm Z=7 e, portanto, sete prótons; diferem no número de nêutrons.","O símbolo N indica apenas a quantidade de nêutrons, não o elemento."],"correctAnswer":"Ambos têm Z=7 e, portanto, sete prótons; diferem no número de nêutrons.","explanation":"O elemento nitrogênio tem Z=7. Os isótopos conservam prótons e diferem em nêutrons: 7 em N-14 e 8 em N-15.","errorFocus":"Confundir mudança de massa com mudança do número atômico.","hint":"Identifique o elemento pelo símbolo e Z; calcule os nêutrons subtraindo Z de A.","misconceptions":{"Ambos têm A=7 e diferem no número de elétrons.":["CONFUNDIR_MUDAN_A_DE_MASSA_COM_MUDAN_A_DO_N_MERO_AT_MICO"]},"position":3},{"id":"v5-chem-atomic-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"READ_NOTATION","contextFamily":"ATOMIC_SYMBOL_POSITION_REVIEW","statement":"Na escrita nuclear de um átomo, o número inferior à esquerda do símbolo químico é Z. O que esse número informa?","options":["A soma de prótons e nêutrons do núcleo.","A quantidade de elétrons perdidos pelo átomo.","A quantidade de nêutrons sem relação com o elemento.","A quantidade de prótons e, assim, a identidade do elemento."],"correctAnswer":"A quantidade de prótons e, assim, a identidade do elemento.","explanation":"O índice inferior esquerdo é o número atômico Z, igual ao número de prótons. O número de massa A aparece na posição superior esquerda.","errorFocus":"Confundir a posição do número atômico com o número de massa ou com a carga.","hint":"Leia a posição antes de interpretar: inferior esquerdo é Z; superior esquerdo é A.","misconceptions":{"A soma de prótons e nêutrons do núcleo.":["CONFUNDIR_A_POSI_O_DO_N_MERO_AT_MICO_COM_O_N_MERO_DE_MASSA_OU_COM_A_CARGA"]},"position":4},{"id":"v5-chem-atomic-review-05","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CHLORINE_AVERAGE_MASS_CLAIM","statement":"A tabela periódica mostra massa atômica média do cloro próxima de 35,5 u. Um aluno conclui que todo átomo de cloro tem 35,5 núcleons. Qual correção é adequada?","options":["A média resulta das abundâncias de isótopos; cada núcleo tem número de massa inteiro.","A conclusão está certa porque a massa atômica é sempre A de cada átomo.","O cloro não possui prótons, então a média não descreve núcleos.","O valor 35,5 significa que metade dos átomos perdeu um nêutron."],"correctAnswer":"A média resulta das abundâncias de isótopos; cada núcleo tem número de massa inteiro.","explanation":"O valor tabelado é uma média ponderada da composição isotópica natural. Um átomo individual tem número inteiro de prótons e nêutrons, portanto A inteiro.","errorFocus":"Tratar a massa atômica média como número de massa de cada átomo individual.","hint":"Diferencie a massa média de uma amostra do valor A de um nuclídeo.","misconceptions":{"A conclusão está certa porque a massa atômica é sempre A de cada átomo.":["TRATAR_A_MASSA_AT_MICA_M_DIA_COMO_N_MERO_DE_MASSA_DE_CADA_TOMO_INDIVIDUAL"]},"position":5},{"id":"v5-chem-atomic-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"ELEMENT_IDENTITY_CHANGE_REVIEW","statement":"Uma reação química transfere elétrons entre átomos, mas não envolve transformação nuclear. Qual alteração seria necessária para que uma espécie passasse a ser outro elemento?","options":["Mudar o número de elétrons, mantendo os prótons.","Mudar o número de prótons do núcleo; mudar elétrons altera apenas a carga.","Mudar o número de nêutrons, mantendo os prótons.","Mudar o número de massa por qualquer transferência eletrônica."],"correctAnswer":"Mudar o número de prótons do núcleo; mudar elétrons altera apenas a carga.","explanation":"A identidade química é definida por Z, a quantidade de prótons. Transferências eletrônicas formam íons; mudar nêutrons produz outro isótopo do mesmo elemento.","errorFocus":"Confundir formação de íon ou isótopo com mudança do elemento.","hint":"Pergunte qual contagem determina Z; mudanças apenas em E ou N não trocam o elemento.","misconceptions":{"Mudar o número de elétrons, mantendo os prótons.":["CONFUNDIR_FORMA_O_DE_ON_OU_IS_TOPO_COM_MUDAN_A_DO_ELEMENTO"]},"position":6}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-chemistry-atomic-structure',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-chemistry-atomic-structure' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'CHEMISTRY', 'ATOMOS', 'numero atomico, isotopos e ions',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

